const body = $input.first().json.body || $input.first().json;

const orderId = body.orderId || 'ORD-UNKNOWN';
const orderNumber = body.orderNumber || orderId;
const customerName = body.customerName || 'Valued Customer';
const customerEmail = body.customerEmail || 'customer@example.com';
const depositAmount = Number(body.depositAmount) || 500000;

const details = body.inspectionDetails || {};
const unitCondition = details.unitCondition || (body.condition === 'DAMAGED' ? 'DAMAGED' : 'GOOD');
const cableReturned = details.cableReturned !== false;
const pouchReturned = details.pouchReturned !== false;
const chargerReturned = details.chargerReturned !== false;

let calculatedDeduction = 0;
const deductions = [];
if (!cableReturned) {
  calculatedDeduction += 50000;
  deductions.push('USB-C Cable (Rp 50.000)');
}
if (!pouchReturned) {
  calculatedDeduction += 50000;
  deductions.push('Travel Pouch (Rp 50.000)');
}
if (!chargerReturned) {
  calculatedDeduction += 50000;
  deductions.push('Wall Charger (Rp 50.000)');
}
if (unitCondition === 'DAMAGED') {
  calculatedDeduction += 350000;
  deductions.push('Unit Damage Penalty (Rp 350.000)');
}

const deductionFee = body.deductionFee !== undefined ? Number(body.deductionFee) : calculatedDeduction;
const refundAmount = body.refundAmount !== undefined ? Number(body.refundAmount) : Math.max(0, depositAmount - deductionFee);
const status = body.status || (deductionFee === 0 ? 'RELEASED' : refundAmount > 0 ? 'PARTIAL' : 'HELD');

const isFullRelease = status === 'RELEASED';
const isPartial = status === 'PARTIAL';
const embedColor = isFullRelease ? 3066993 : isPartial ? 15844367 : 15158332;

const title = isFullRelease
  ? '[PASSED] Unit Inspection Approved & Full Deposit Released'
  : isPartial
  ? '[PARTIAL] Inspection Complete - Partial Deposit Released'
  : '[HELD] Physical Damage / Incomplete - Deposit Withheld';

const description = isFullRelease
  ? `Physical inspection and accessories check for customer **${customerName}** passed all quality checks.`
  : isPartial
  ? `Physical inspection noted deductions (${deductions.join(', ')}). Net refund processed.`
  : `Unit returned with heavy damages/missing parts (${deductions.join(', ')}). Full deposit withheld for repair review.`;

const message = isFullRelease
  ? `Security deposit refund of Rp ${refundAmount.toLocaleString('id-ID')} processed successfully to customer account.`
  : isPartial
  ? `Inspection completed with deductions of Rp ${deductionFee.toLocaleString('id-ID')}. Partial refund of Rp ${refundAmount.toLocaleString('id-ID')} released.`
  : `Unit damaged or incomplete. Full deposit of Rp ${depositAmount.toLocaleString('id-ID')} held pending repair review.`;

return [{
  json: {
    orderId,
    orderNumber,
    customerName,
    customerEmail,
    depositAmount,
    refundAmount,
    deductionFee,
    status,
    condition: body.condition || (isFullRelease ? 'PASSED' : unitCondition === 'DAMAGED' ? 'DAMAGED' : 'INCOMPLETE'),
    processedAt: new Date().toISOString(),
    message,
    discordPayload: {
      content: '**[AirFi Ops ERP] Device Return & Deposit Refund Report**',
      embeds: [
        {
          title,
          description,
          color: embedColor,
          fields: [
            { name: 'Order Number', value: String(orderNumber), inline: true },
            { name: 'Customer', value: String(customerName), inline: true },
            { name: 'Unit Condition', value: String(unitCondition), inline: true },
            { name: 'Held Deposit', value: `Rp ${depositAmount.toLocaleString('id-ID')}`, inline: true },
            { name: 'Deduction Fee', value: `Rp ${deductionFee.toLocaleString('id-ID')}`, inline: true },
            { name: 'Net Refund', value: `Rp ${refundAmount.toLocaleString('id-ID')}`, inline: true },
            { name: 'Deposit Status', value: String(status), inline: true }
          ],
          footer: {
            text: 'AirFi Ops ERP - Automated via n8n Engine'
          },
          timestamp: new Date().toISOString()
        }
      ]
    }
  }
}];
